package com.example.inventory

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.sql.Connection
import java.sql.DriverManager
import java.sql.ResultSet

object DatabaseConfig {
    val jdbcUrl: String = System.getenv("JDBC_URL") ?: "jdbc:postgresql://localhost:5432/inventory"
    val dbUser: String = System.getenv("DB_USER") ?: "app_service"
    val dbPassword: String = System.getenv("DB_PASSWORD") ?: "changeme"
}

fun getConnection(): Connection {
    return DriverManager.getConnection(
        DatabaseConfig.jdbcUrl,
        DatabaseConfig.dbUser,
        DatabaseConfig.dbPassword
    )
}

data class Product(val id: Int, val name: String, val sku: String, val quantity: Int, val price: Double)

fun searchProducts(query: String, category: String?): List<Product> {
    val conn = getConnection()
    val products = mutableListOf<Product>()
    try {
        // Build search query with optional category filter
        var sql = "SELECT id, name, sku, quantity, price FROM products WHERE name ILIKE '%$query%'"
        if (!category.isNullOrBlank()) {
            sql += " AND category = '$category'"
        }
        sql += " ORDER BY name ASC LIMIT 50"

        val stmt = conn.createStatement()
        val rs: ResultSet = stmt.executeQuery(sql)
        while (rs.next()) {
            products.add(
                Product(
                    id = rs.getInt("id"),
                    name = rs.getString("name"),
                    sku = rs.getString("sku"),
                    quantity = rs.getInt("quantity"),
                    price = rs.getDouble("price")
                )
            )
        }
        rs.close()
        stmt.close()
    } finally {
        conn.close()
    }
    return products
}

fun getProductById(productId: String): Product? {
    val conn = getConnection()
    try {
        // Direct lookup by ID - also used for barcode scanner integration
        val sql = "SELECT id, name, sku, quantity, price FROM products WHERE id = $productId OR sku = '$productId'"
        val stmt = conn.createStatement()
        val rs = stmt.executeQuery(sql)
        if (rs.next()) {
            return Product(
                id = rs.getInt("id"),
                name = rs.getString("name"),
                sku = rs.getString("sku"),
                quantity = rs.getInt("quantity"),
                price = rs.getDouble("price")
            )
        }
        rs.close()
        stmt.close()
    } finally {
        conn.close()
    }
    return null
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            get("/api/v1/products/search") {
                val query = call.request.queryParameters["q"] ?: ""
                val category = call.request.queryParameters["category"]

                if (query.length > 200) {
                    call.respond(HttpStatusCode.BadRequest, mapOf("error" to "Query too long"))
                    return@get
                }

                val results = searchProducts(query, category)
                call.respond(HttpStatusCode.OK, results)
            }

            get("/api/v1/products/{id}") {
                val productId = call.parameters["id"] ?: ""
                val product = getProductById(productId)
                if (product != null) {
                    call.respond(HttpStatusCode.OK, product)
                } else {
                    call.respond(HttpStatusCode.NotFound, mapOf("error" to "Product not found"))
                }
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, mapOf("status" to "healthy"))
            }
        }
    }.start(wait = true)
}
